cd /home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/roadmap/items && python3 - <<'PY'
import yaml,glob
items={}
for p in glob.glob('*.yaml'):
    d=yaml.safe_load(open(p)); items[d['id']]=d
act=[d for d in items.values() if d.get('status')=='active']
print('total',len(items),'active',len(act))
for d in sorted(act,key=lambda x:x['id']): print('  ',d['id'],'|owner',repr(d.get('owner')),'|ms',repr(d.get('milestone')))
# parent/child consistency
kids={}
for d in items.values():
    if d.get('parent'): kids.setdefault(d['parent'],[]).append(d)
print()
for pid,ks in sorted(kids.items()):
    p=items.get(pid)
    if not p: continue
    open_k=[k['id'] for k in ks if k.get('status') not in ('done','rejected')]
    if p.get('status')=='done' and open_k: print('DONE PARENT w/ open kids:',pid,open_k)
    if p.get('status') not in ('done','rejected') and not open_k: print('ALL KIDS DONE, parent',p.get('status'),':',pid,[k['id'] for k in ks])
